package com.example._6_security.mapper;

import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingTarget;

import com.example._6_security.dto.AuthorRequestDto;
import com.example._6_security.dto.AuthorResponseDto;
import com.example._6_security.dto.AuthorSummaryDto;
import com.example._6_security.model.Author;

/**
 * MapStruct mapper for Author. componentModel = "spring" makes the generated
 * AuthorMapperImpl an injectable Spring bean. Request -> entity mapping ignores
 * the id (generated by the DB) and the books back-reference (owned elsewhere).
 */
@Mapper(componentModel = "spring")
public interface AuthorMapper {

    AuthorResponseDto toResponse(Author author);

    AuthorSummaryDto toSummary(Author author);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "books", ignore = true)
    Author toEntity(AuthorRequestDto dto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "books", ignore = true)
    void updateEntity(AuthorRequestDto dto, @MappingTarget Author author);
}
